import { StatCard } from '@bindshq/stance-react';

export function WithChart() {
  const points = [12, 18, 15, 22, 26, 24, 31, 35];
  const max = Math.max(...points);
  const d = points
    .map(
      (p, i) => `${i === 0 ? 'M' : 'L'}${(i / (points.length - 1)) * 100},${40 - (p / max) * 36}`,
    )
    .join(' ');
  return (
    <StatCard
      label="New users"
      value="35"
      delta="18%"
      trend="up"
      comparison="this week"
      chart={
        <svg viewBox="0 0 100 40" preserveAspectRatio="none" aria-hidden="true">
          <path
            d={d}
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            vectorEffect="non-scaling-stroke"
          />
        </svg>
      }
      footer={<a href="#users">View all users</a>}
      style={{ width: 300 }}
    />
  );
}

